from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class RadDomain(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    name = SchemaField(name='name', not_null=True)

    def __init__(self, id, name):
        self.id = id
        self.name = name

        super(RadDomain, self).__init__()


class RadDomainResponse(SchemaObject):
    operation_id = SchemaField(name='operationId', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='errorMessage', optional=True)
    rad_domains = SchemaField(name='radDomains', many=True, klass=RadDomain, optional=True)

    def __init__(self, operation_id, status, error_message, rad_domains):
        self.operation_id = operation_id
        self.status = status
        self.error_message = error_message
        self.rad_domains = rad_domains

        super(RadDomainResponse, self).__init__()
